"rb_agent_fr24":{"message0":"ንዋያተ Flightradar24","tooltip":"ይሁብ ለላእክ ንዋያተ Flightradar24 ለሊሁ፡ መካናተ አርጋብ ዘሰማይ ሕያዋን (በመካን፣ በኍልቈ ሠረራ፣ በስመ ጽዋዔ አው በመዝገብ)፣ ዜና ሠረራት ምስለ ተንሥኦት ወርደት፣ ፍናዋት፣ ዜና እስከ 2016፣ ወነገረ ማኅበራተ ሠረራ ወመካናተ ሠረራ። ኵሉ ንዋይ ያነብብ ባሕቲቱ። ይፈቅድ Node.js ዘተተክለ፣ ወ FR24_API_KEY ውስተ second-thought.ini (ምዝጋብ ዘበሤጥ እም fr24api.flightradar24.com፤ ኵሉ ጽዋዔ ያወፅእ credits፣ በእንተዝ መስፈርት አው ወሰነ መዓርጋት የዐቅብ ሩጸተ ኅሱረ)። በ Python ዘወፅአ ባሕቲቱ።"},
