"Programs other people shared. Each was checked before it was added, and says what it can do, worked out from its blocks. To share one of yours, see gallery/README.md in the Second Thought folder.":"ሥርዐታት ዘአካፈሉ ካልኣን። ኵሉ ተሐተተ ቅድመ ይትወሰክ፣ ወይነግር ዘይክል ይግበር፣ ዘተረክበ እምግንፋላቲሁ። ከመ ታካፍል አሐደ እምዘዚአከ፣ ነጽር gallery/README.md ውስተ ቤተ መጻሕፍት ዘ Second Thought።",
"Saved programs and prompts":"ሥርዐታት ወትእዛዛተ ቃል ዘተዐቅቡ",
