"Reusable prompt text. Drop the 'prompt' block (in Ask Claude) into any slot and type the prompt's name.":"ጽሑፈ ትእዛዝ ዘይትበቋዕ ዳግመ። ደይ ግንፋለ 'ትእዛዘ ቃል' (በስአል Claude) ውስተ ዘኮነ መካን ወጸሐፍ ስመ ትእዛዝ።",
