"Text":"ጽሑፍ",
"Save prompt":"ዕቀብ ትእዛዘ ቃል",
"In this page, the Home Assistant blocks use a <b>sample house</b>, so you can build and test safely. Change a state below (press Enter) to try your 'when … changes' scripts. Exported Python connects to your real Home Assistant: set HA_URL and HA_TOKEN (a long-lived access token from your Home Assistant profile, under Security).":"በዝንቱ ገጽ፣ ግንፋላተ Home Assistant ይትበቋዑ በ<b>ቤተ አርአያ</b>፣ ከመ ትሕንጽ ወትፈትን በዳኅን። ወልጥ ህላዌ በታሕቱ (ጥቅዕ Enter) ከመ ትፈትን ፍኖታቲከ 'ሶበ … ይትዌለጥ'። Python ዘወፅአ ይትራከብ ምስለ Home Assistant ዘዚአከ እሙን፡ አንብር HA_URL ወ HA_TOKEN (token ዘነዊኅ ዕድሜሁ እምገጽከ በ Home Assistant፣ ታሕተ Security)።",
"Filter entities":"ፍልጥ entities",
"Filter, e.g. light or kitchen":"ፍልጥ፣ ከመ light አው kitchen",
