"Forget everything in memory? This can't be undone.":"ትረስዕኑ ኵሎ ዘውስተ ዝክር? ዝንቱ ኢይትመየጥ።",
"Keep it":"ዕቀቦ",
"Backup models":"አምሳላተ ዕቅበት",
"The <b>Model</b> menu is your primary model: it does every step. If it fails on a step (no key, out of credit, service down or unreachable), the first backup answers that step instead, then the second, then the third. The run log says each time a backup steps in.":"ምርጫ <b>አምሳል</b> ውእቱ አምሳልከ ቀዳሚ፡ ይገብር ኵሎ መዓርገ። እመ ወድቀ በመዓርግ (አልቦ መርኆ፣ ኀልቀ credit፣ አገልግሎት ወድቀ አው ኢይትረከብ)፣ አምሳለ ዕቅበት ቀዳሚ ያወሥእ ውእተ መዓርገ ህየንቴሁ፣ ወእምዝ ካልእ፣ ወእምዝ ሣልስ። መዝገበ ሩጸት ይነግር ኵሎ ጊዜ ሶበ ይበውእ አምሳለ ዕቅበት።",
"Blocks that name their own model, such as <b>with model</b>, keep that model, so a panel of judges stays a panel of different judges.":"ግንፋላት እለ ይሰምዩ አምሳሎሙ፣ ከመ <b>በአምሳል</b>፣ የዐቅቡ ውእተ አምሳለ፣ ከመ ይንበር ጉባኤ መኳንንት ጉባኤ መኳንንት ዘዘዚአሆሙ።",
