"Drag blocks from the categories; drag a block back onto them to delete it. Round slots take values, hexagon slots take yes/no conditions.":"ስሐብ ግንፋላተ እምክፍላት፤ ስሐብ ግንፋለ ላዕሌሆሙ ዳግመ ከመ ትደምስሶ። መካናት ክቡባን ይነሥኡ ዐቅማተ፣ መካናት ዘስድስቱ ገቦ ይነሥኡ መፍቅደ እወ/አልቦ።",
