"Saved prompt “{name}”. Use it with the 'prompt' block.":"ተዐቅበ ትእዛዘ ቃል “{name}”። ተበቋዕ ቦቱ በግንፋለ 'ትእዛዘ ቃል'።",
"Saved to your account for this page. Only you can see them.":"ተዐቅበ ውስተ መዝገብከ ለዝንቱ ገጽ። አንተ ባሕቲትከ ትክል ትርአዮሙ።",
"Saved {file}.":"ተዐቅበ {file}።",
"Saved {name}.zip. Unzip it, put your keys in second-thought.ini, then run {name}.py (on Windows, double-click run.bat).":"ተዐቅበ {name}.zip። ፍትሖ፣ ደይ መራኁቲከ ውስተ second-thought.ini፣ ወእምዝ ሩጽ {name}.py (በ Windows፣ ጥቅዕ ካዕበ run.bat)።",
"Saved “{name}”.":"ተዐቅበ “{name}”።",
"Saving files isn't available here. Use Copy Python code instead.":"ዐቂበ መጻሕፍት ኢሀሎ በዝየ። ተበቋዕ በቅዳሕ ጽሕፈተ Python ህየንቴሁ።",
"Saving files isn't available here. Use Copy as text instead.":"ዐቂበ መጻሕፍት ኢሀሎ በዝየ። ተበቋዕ በቅዳሕ ከመ ጽሑፍ ህየንቴሁ።",
"Saving isn't available here. Use Import / export to keep a copy as a file.":"ዕቅበት ኢሀሎ በዝየ። ተበቋዕ በአብእ / አውፅእ ከመ ትዕቀብ ቅጂ ከመ መጽሐፍ።",
"Saving isn't available here. Use Import / export to keep files instead.":"ዕቅበት ኢሀሎ በዝየ። ተበቋዕ በአብእ / አውፅእ ከመ ትዕቀብ መጻሕፍተ ህየንቴሁ።",
"Schedules are on. They run only while this page stays open and your computer is awake. Each run uses your Claude usage.":"ጊዜያት ርኅዋን። ይረውጹ እንዘ ርኅው ዝንቱ ገጽ ወንቁህ መኈልቍከ ባሕቲቱ። ኵሉ ሩጸት ይትበቋዕ በበቍዔተ Claude ዘዚአከ።",
"That couldn't be saved ({problem}).":"ዝንቱ ኢተዐቅበ ({problem})።",
"That file is over 5 MB, which is too big for a program file.":"ውእቱ መጽሐፍ የዐቢ እም 5 MB፣ ዘፈድፋደ ዐቢይ ለመጽሐፈ ሥርዐት።",
"That isn't valid program text. Export a program from this page and import that file.":"ዝንቱ ኢኮነ ጽሑፈ ሥርዐት ርቱዐ። አውፅእ ሥርዐተ እምዝንቱ ገጽ ወአብእ ውእተ መጽሐፈ።",
"That program couldn't be opened, so the canvas was left as it was.":"ውእቱ ሥርዐት ኢተርኅወ፣ በእንተዝ ተኀድገ ሰሌዳ በከመ ሀሎ።",
"That saved program is damaged and can't be opened.":"ውእቱ ሥርዐት ዘተዐቅበ ተሐጕለ ወኢይትረኀው።",
"That zip couldn't be opened: {problem}.":"ውእቱ zip ኢተርኅወ፡ {problem}።",
"That's too big to save (over 240 KB).":"ዝንቱ ፈድፋደ ዐቢይ ለዕቅበት (የዐቢ እም 240 KB)።",
"The code couldn't be generated: {problem}":"ጽሕፈት ኢተፈጥረ፡ {problem}",
"The file couldn't be read. Try choosing it again.":"መጽሐፍ ኢተነበ። ፈትን ትኅረዮ ዳግመ።",
"The program couldn't be loaded, so your canvas was left as it was. ({problem})":"ሥርዐት ኢተርኅወ፣ በእንተዝ ተኀድገ ሰሌዳከ በከመ ሀሎ። ({problem})",
"This code was exported from here and then edited. The blocks saved inside it are from before the edits.":"ዝንቱ ጽሕፈት ወፅአ እምዝየ ወእምዝ ተአረመ። ግንፋላት ዘተዐቅቡ በውስጡ እምቅድመ አርሞ እሙንቱ።",
"This code wasn't exported from this page. Claude can try to turn it into blocks. That uses your Claude usage, and you can undo it afterwards.":"ዝንቱ ጽሕፈት ኢወፅአ እምዝንቱ ገጽ። Claude ይክል ይፈትን ይወልጦ ኀበ ግንፋላት። ዝንቱ ይትበቋዕ በበቍዔተ Claude ዘዚአከ፣ ወትክል ትኅድጎ እምድኅሬሁ።",
"This doesn't look like a Second Thought program. Export one from this page and import that file.":"ዝንቱ ኢይመስል ሥርዐተ Second Thought። አውፅእ አሐደ እምዝንቱ ገጽ ወአብእ ውእተ መጽሐፈ።",
"This program uses blocks this page doesn't have: {blocks}.":"ዝንቱ ሥርዐት ይትበቋዕ በግንፋላት ዘአልቦ ለዝንቱ ገጽ፡ {blocks}።",
"Type a name for this program first.":"ጸሐፍ ስመ ለዝንቱ ሥርዐት ቅድመ።",
