"while page is open":"እንዘ ርኅው ገጽ",
"{list} and {last}":"{list} ወ {last}",
"'let me choose from' got an empty list.":"'ኅድገኒ እኅረይ እም' ተመጠወ ዝርዝረ ዕራቀ።",
"'{k} of' needs a record in its second slot.":"'{k} ዘ' ይፈቅድ ጦማረ በመካኑ ካልእ።",
"'{name}' called itself too many times.":"'{name}' ጸውዐ ርእሶ ብዙኀ ጊዜ ፈድፋደ።",
