"(no entity)":"(አልቦ entity)",
"(no message yet: only messages the broker keeps show up straight away)":"(አልቦ መልእክት ዓዲ፡ መልእክታት ዘየዐቅብ broker ባሕቲቶሙ ያስተርእዩ ሶቤሃ)",
"(no records)":"(አልቦ ጦማራት)",
"(no result)":"(አልቦ ፍሬ)",
"(no subject)":"(አልቦ ርእስ)",
