"emails":"መልእክታተ email",
"news feeds":"ዜናት",
"none":"አልቦ",
"nothing":"አልቦ ምንትኒ",
"nothing usable":"አልቦ ዘይበቍዕ",
"plans first":"ይመክር ቅድመ",
"read_email needs an email's id number, from search_email.":"read_email ይፈቅድ ኍልቈ id ዘ email፣ እም search_email።",
"read_page needs a web address starting with http:// or https://.":"read_page ይፈቅድ መካነ መርበብ ዘይወጥን በ http:// አው https://።",
"remember needs a name.":"remember ይፈቅድ ስመ።",
"review_text needs criteria to check against.":"review_text ይፈቅድ ሕግጋተ ለሐተታ።",
