"search_memory needs some words to look for.":"search_memory ይፈቅድ ቃላተ ለኅሠሣ።",
"search_web needs a query.":"search_web ይፈቅድ ጥያቄ።",
"sending messages and announcements":"ፈንዎተ መልእክታት ወዜናት",
"smart home actions, messages and saving files":"ግብራተ ቤት ጠቢብ፣ መልእክታት ወዐቂበ መጻሕፍት",
"time_plus needs a time like 09:30 or 2026-10-10 09:30, not “{when}”.":"time_plus ይፈቅድ ጊዜ ከመ 09:30 አው 2026-10-10 09:30፣ አኮ “{when}”።",
"up to {n} steps":"እስከ {n} መዓርጋት",
"with {data}":"ምስለ {data}",
"{device} has no “{cap}”. It has: {caps}.":"{device} አልቦቱ “{cap}”። ቦቱ፡ {caps}።",
"{label} ({left} left)":"{label} ({left} ተርፈ)",
"{model} failed: {problem}\nTrying {next} instead.":"{model} ወድቀ፡ {problem}\nይፈትን {next} ህየንቴሁ።",
"{n} characters":"{n} ፊደላት",
"{n} script started":"{n} ፍኖት ወጠነ",
"{n} script started, waiting for it to finish":"{n} ፍኖት ወጠነ፣ ይጸንሕ እስከ ይፌጽም",
"{n} scripts started":"{n} ፍኖታት ወጠኑ",
"{n} scripts started, waiting for them to finish":"{n} ፍኖታት ወጠኑ፣ ይጸንሕ እስከ ይፌጽሙ",
"{service} on {entity} was refused, so nothing happened.":"{service} ላዕለ {entity} ተከልአ፣ በእንተዝ አልቦ ዘኮነ።",
"{service} was refused, so nothing happened.":"{service} ተከልአ፣ በእንተዝ አልቦ ዘኮነ።",
"{who} can't be reached from this page, so Claude answers in its place. Export to Python to use {who} itself.":"{who} ኢይትረከብ እምዝንቱ ገጽ፣ በእንተዝ Claude ያወሥእ ህየንቴሁ። አውፅእ ኀበ Python ከመ ትትበቋዕ በ {who} ለሊሁ።",
"“{hhmm}” isn't a time like 09:00.":"“{hhmm}” ኢኮነ ጊዜ ከመ 09:00።",
"“{kind}” isn't a type the agent knows. Use text, number, yes/no, list or any (for “{name}”).":"“{kind}” ኢኮነ ዘመደ ዘየአምር ላእክ። ተበቋዕ በ text, number, yes/no, list አው any (ለ“{name}”)።",
"“{name}” can't run while other scripts are running at the same time. Run it from a script that runs on its own (not alongside a broadcast).":"“{name}” ኢይክል ይሩጽ እንዘ ይረውጹ ፍኖታት ካልኣን በአሐዱ ጊዜ። ሩጾ እምፍኖት ዘይረውጽ ባሕቲቱ (አኮ ምስለ ስብከት)።",
"“{repo}” isn't a GitHub project. Use owner/name, like octocat/hello-world.":"“{repo}” ኢኮነ ግብረ GitHub። ተበቋዕ በ owner/name፣ ከመ octocat/hello-world።",
"“{shown}” isn't a real date.":"“{shown}” ኢኮነ ዕለተ እሙነ።",
"“{shown}” isn't a time.":"“{shown}” ኢኮነ ጊዜ።",
"“{svc}” isn't a service name. Use domain.service, for example light.turn_off.":"“{svc}” ኢኮነ ስመ አገልግሎት። ተበቋዕ በ domain.service፣ በአርአያ light.turn_off።",
"“{text}” isn't a day. Use today, tomorrow, a weekday or YYYY-MM-DD.":"“{text}” ኢኮነ ዕለተ። ተበቋዕ በ today, tomorrow፣ ዕለተ ሱባዔ አው YYYY-MM-DD።",
"“{to}” isn't an email address.":"“{to}” ኢኮነ መካነ email።",
"“{value}” isn't a number.":"“{value}” ኢኮነ ኍልቈ።",
"“{value}” isn't on or off.":"“{value}” ኢኮነ on አው off።",
