"Shared by {author}.":"ዘአካፈለ {author}።",
"{title} (shared by {author})":"{title} (ዘአካፈለ {author})",
"GitHub issue opened in {repo}: #{n}":"ተርኅወ issue ዘ GitHub በ {repo}፡ #{n}",
"GitHub labels on {repo} #{n}":"ማኅተማተ GitHub በ {repo} #{n}",
"comment on GitHub, and open and label issues":"ይተረጕም በ GitHub፣ ወያርኁ ወየኀትም issues",
"Community: GitHub":"ማኅበር፡ GitHub",
"Community: code and data":"ማኅበር፡ ጽሕፈተ መኈልቍ ወነገር",
