"Community: money":"ማኅበር፡ ንዋይ",
"Community: calendar and email":"ማኅበር፡ ባሕረ ሐሳብ ወ email",
"Community: home and baking":"ማኅበር፡ ቤት ወኅብዘት",
"Community: odds and ends":"ማኅበር፡ ዘዘዚአሁ",
"look at the files in a folder, and watch it for new ones":"ይኔጽር መጻሕፍተ በቤተ መጻሕፍት፣ ወየዐቅቦ ለሐደስት",
"The setup check only runs in exported Python: export this program and run it there to see the report.":"ሐተታ ድልወት ትረውጽ በ Python ዘወፅአ ባሕቲቱ፡ አውፅእ ዘንተ ሥርዐተ ወሩጾ ህየ ከመ ትርአይ ዜና።",
"Save as GitHub Actions (.zip)":"ዕቀብ ከመ GitHub Actions (.zip)",
"it has no 'when it's' or 'every' script, so there's nothing to run on a schedule":"አልቦቱ ፍኖተ 'ሶበ ይከውን' አው 'በበ'፣ በእንተዝ አልቦ ዘይረውጽ በጊዜ",
"it waits for things to happen, like messages, web requests or changes, and GitHub Actions only runs it at set times":"ይጸንሕ ነገራተ ከመ ይኩኑ፣ ከመ መልእክታት፣ ስእለታተ መርበብ አው ተውላጣት፣ ወ GitHub Actions ይረውጾ በጊዜያት ዘተወሰኑ ባሕቲቱ",
"it uses Llama, MCP servers or folders on your own computer, which GitHub can't reach":"ይትበቋዕ በ Llama፣ አገልጋያነ MCP አው አብያተ መጻሕፍት በመኈልቍከ፣ ዘኢይክል GitHub ይብጽሖሙ",
"it asks you questions while it runs, and nobody is there to answer":"ይሴአለከ ጥያቄያተ እንዘ ይረውጽ፣ ወአልቦ ሰብእ ህየ ዘያወሥእ",
"This program can't run on GitHub Actions: {why}.":"ዝንቱ ሥርዐት ኢይክል ይሩጽ በ GitHub Actions፡ {why}።",
"Saved {name}-actions.zip. Put its files in a private GitHub repository and add the secrets SETUP.md lists; then it runs on schedule.":"ተዐቅበ {name}-actions.zip። ደይ መጻሕፍቲሁ ውስተ repository ኅቡእ ዘ GitHub ወወስክ secrets ዘይዜኑ SETUP.md፤ ወእምዝ ይረውጽ በጊዜሁ።",
"Describe a program":"ንግር ሥርዐተ",
"Describe a program, like: every Friday at 6pm, find the best two hours this weekend to dry washing and send it to me on Telegram":"ንግር ሥርዐተ፣ ከመ፡ በኵሉ ዓርብ በ 6 ሰዓተ ምሴት፣ ርከብ ክልኤተ ሰዓታተ ዘይኄይሱ በዛቲ ሰንበት ለአይብሶ አልባስ ወፈንዎ ሊተ በ Telegram",
"Build it":"ሕንጾ",
"Change this program":"ወልጥ ዘንተ ሥርዐተ",
"Load it":"አርኅዎ",
"Discard":"ግድፍ",
"Undo":"ኅድግ ዘገበርከ",
"Describe what the program should do first.":"ንግር ዘይደሉ ይግበር ሥርዐት ቅድመ።",
"Building a program needs Claude. Open this page in claude.ai while signed in.":"ሐኒጸ ሥርዐት ይፈቅድ Claude። አርኅው ዘንተ ገጸ በ claude.ai እንዘ ቦእከ።",
"Claude is working on the program. This can take a minute…":"Claude ይገብር ሥርዐተ። ይነሥእ ደቂቀ…",
"Claude's reply wasn't a block program. Try again, or describe it more simply.":"ተሰጥዎተ Claude ኢኮነ ሥርዐተ ግንፋላት። ፈትን ዳግመ፣ አው ንግሮ በዘይቀልል።",
"Claude used blocks this page doesn't have ({blocks}), so nothing was loaded. Try again, or describe it differently.":"Claude ተበቍዐ በግንፋላት ዘአልቦ ለዝንቱ ገጽ ({blocks})፣ በእንተዝ አልቦ ዘተርኅወ። ፈትን ዳግመ፣ አው ንግሮ በካልእ።",
"{n} blocks.":"{n} ግንፋላት።",
"Left out: {notes}.":"ተኀድገ፡ {notes}።",
"Loading it replaces the program on the canvas; you can undo straight after.":"አርኅዎቱ ይዌልጥ ሥርዐተ ዘበሰሌዳ፤ ትክል ትኅድጎ ሶቤሃ እምድኅሬሁ።",
"Building the program failed: {problem}":"ሐኒጸ ሥርዐት ወድቀ፡ {problem}",
"Undone. Your previous program is back.":"ተኀድገ። ሥርዐትከ ዘቀደመ ተመይጠ።",
"Loaded Claude's program ({n} blocks). Check the blocks before running.":"ተርኅወ ሥርዐተ Claude ({n} ግንፋላት)። ሕትት ግንፋላተ ቅድመ ትሩጽ።",
"Community: teaching":"ማኅበር፡ ትምህርት",
"This program was saved by a newer Second Thought (block format {theirs}; this page reads up to {ours}). Open it on the newest page.":"ዝንቱ ሥርዐት ተዐቅበ በ Second Thought ዘይሔድስ (አምሳለ ግንፋላት {theirs}፤ ዝንቱ ገጽ ያነብብ እስከ {ours})። አርኅዎ በገጽ ዘሐዲስ።",
"It was saved with older blocks and has been brought up to date (block format {from} to {to}).":"ተዐቅበ በግንፋላት ብሉያን ወተሐደሰ (አምሳለ ግንፋላት {from} ኀበ {to})።",
"A file was too big to keep, so that step will ask when the test runs.":"መጽሐፍ ዐቢይ ፈድፋደ ለዕቅበት፣ በእንተዝ ውእቱ መዓርግ ይሴአል ሶበ ትረውጽ ፈተና።",
"It doesn't yet meet the criteria.":"ኢይፌጽም ሕግጋተ ዓዲ።",
"Run tests ({n})":"ሩጽ ፈተናተ ({n})",
"Save as test case":"ዕቀብ ከመ ፈተና",
"Save test":"ዕቀብ ፈተና",
"Saved. Run tests checks it again whenever you like; exported, it's in the zip for python my-program.py --test.":"ተዐቅበ። ሩጽ ፈተናተ ይሔትቶ ዳግመ ሶበ ፈቀድከ፤ እመ ወፅአ፣ ሀሎ ውስተ zip ለ python my-program.py --test።",
"Say what the result must do first.":"በል ዘይደሉ ይግበር ፍሬ ቅድመ።",
"Test answer":"ተሰጥዎተ ፈተና",
"Test cases don't keep pictures, so a test can't choose one. Test this part by running the program.":"ፈተናት ኢየዐቅቡ ሥዕላተ፣ በእንተዝ ፈተና ኢትክል ትኅረይ አሐደ። ፈትን ዘንተ ክፍለ በሩጸተ ሥርዐት።",
"Test check: {name}":"ሐተታ ፈተና፡ {name}",
"Test name":"ስመ ፈተና",
"Test {n}":"ፈተና {n}",
