"Tests":"ፈተናት",
"The run stopped.":"ቆመት ሩጸት።",
"The test case has no answer for this step ({what}). Save it again from a run that gets this far.":"ፈተና አልባቲ ተሰጥዎ ለዝንቱ መዓርግ ({what})። ዕቀባ ዳግመ እምሩጸት እንተ ትበጽሕ እስከ ዝየ።",
"What the result must do":"ዘይደሉ ይግበር ፍሬ",
"What the result must do, separated by semicolons, like: under 200 words; names the date":"ዘይደሉ ይግበር ፍሬ፣ ዘተፈልጠ በነቍጥ ወሠረዝ፣ ከመ፡ ዘይንእስ እም 200 ቃላት፤ ይሰሚ ዕለተ",
"passed":"ኀለፈ",
"replayed":"ተደግመ",
"{passed} of {n} passed.":"{passed} እም {n} ኀለፉ።",
"Block editor":"ሐናጼ ግንፋላት",
"Keyboard":"መጥቅዕ ፊደላት",
