"under {cost}":"ዘይንእስ እም {cost}",
"At the models' list prices that's {cost}; on this page it counts toward your Claude usage instead.":"በሤጠ ዝርዝረ አምሳላት ውእቱ {cost}፤ በዝንቱ ገጽ ይትኌለቍ ለበቍዔተ Claude ዘዚአከ ህየንቴሁ።",
"No money budget for this run.":"አልቦ መስፈርተ ወርቅ ለዛቲ ሩጸት።",
"Stopped: a model this run has already used has no known price, so it can't be held to its budget of {budget}. Use models with a price, or a budget in tokens.":"ቆመት፡ አምሳል ዘተበቍዐት ቦቱ ዛቲ ሩጸት ቅድመ አልቦቱ ሤጥ ዘይትዐወቅ፣ በእንተዝ ኢትትዐቀብ በመስፈርታ {budget}። ተበቋዕ በአምሳላት ዘቦሙ ሤጥ፣ አው በመስፈርት ዘ token።",
"Stopped: this run has spent about {cost} at list prices, which reaches its budget of {budget}. Raise the amount in the 'limit this run' block.":"ቆመት፡ ዛቲ ሩጸት አውፅአት ከመ {cost} በሤጠ ዝርዝር፣ ዘይበጽሕ መስፈርታ {budget}። አልዕል መጠነ በግንፋለ 'ወስን ዛተ ሩጸተ'።",
"Stopped: {model} has no known price, so this run can't be held to its budget of {budget}. Use a model with a price, or a budget in tokens.":"ቆመት፡ {model} አልቦቱ ሤጥ ዘይትዐወቅ፣ በእንተዝ ዛቲ ሩጸት ኢትትዐቀብ በመስፈርታ {budget}። ተበቋዕ በአምሳል ዘቦቱ ሤጥ፣ አው በመስፈርት ዘ token።",
"This run stops before a Claude call once it has spent about {budget} at list prices (about {cost} so far).":"ዛቲ ሩጸት ትቀውም ቅድመ ጽዋዔ Claude ሶበ አውፅአት ከመ {budget} በሤጠ ዝርዝር (ከመ {cost} እስከ ይእዜ)።",
