"a_prreview":{"title":"ላእክ፡ ሕትት ወተርጕም pull request","desc":"ይሴአል አይ pull request ይሕትት፣ ያነብቦ፣ ይጽሕፍ ትርጓሜ ሐተታ፣ ያኀትት በሐታቲ ፍሉጥ ከመ ትርጓሜ ርቱዕ ወጥንቁቅ፣ ወእምዝ ይጽሕፎ፣ እንዘ ይሴአለከ ቅድመ።","tip":"በል 'ኢትግበር' ሶበ ይሴአል ይጽሐፍ፣ ከመ ታንብብ ትርጓሜ ዘእንበለ ይትጸሐፍ።"},
"a_inbox":{"title":"ላእክ፡ ፍልጠተ ሣፁነ email","desc":"ያነብብ email ዘዚአከ ዘክልኤቱ መዋዕል ደኃርያን፣ ይፈልጦ ኀበ ዘይፈቅድ ተሰጥዎ፣ ዘይደሉ ለአእምሮ ወዘይትኀደግ፣ ይሔትት ባሕረ ሐሳብከ ለዘቦቱ ዕለት፣ ወይጽሕፍ ተሰጥዎታተ። አልቦ ዘይፌኑ ዘእንበለ ይሰአልከ።","tip":"ይፈቅድ EMAIL_ADDRESS ወቃለ ኅቡእ ዘ app በ Python ዘወፅአ። በል 'አብሕ' ከመ ትፈኑ ተሰጥዎ ዘተጽሕፈ፣ አው 'ኢትግበር' ከመ ትዕቀቦ ከመ ቅድመ ጽሑፍ።"},
"a_week":{"title":"ላእክ፡ ምክር ሱባዔየ","desc":"ይኔጽር ባሕረ ሐሳብከ ለሱባዔ፣ emails ዘዚአከ ዘቅሩብ ወማስታወሻተ ዘፈነውከ ለ bot ዘ Telegram ዘዚአከ፣ ወያመክር ማእዜ ትሕብዝ ወምንተ ይደሉ ይትገበር፣ ምስለ ጊዜያት ዘይሰነአዉ ምስለ ኵሉ ካልእ።","tip":"ፈኑ ለ bot ዘዚአከ ማስታወሻተ ለርእስከ በሱባዔ፣ ከመ 'ተሣየጥ ሐሪጸ ሰገም'። ላእክ ይነሥኦሙ።"},
"a_tgbot":{"title":"bot ዘ Telegram ዘያወሥእ","desc":"ሶበ ትፌኑ መልእክተ ለ bot ዘ Telegram ዘዚአከ፣ ላእክ ያወሥእ፣ እንዘ ይትበቋዕ በባሕረ ሐሳብከ፣ ማስታወሻቲከ ወሐሳብ፣ ወይፌኑ ተሰጥዎ። ጥቅዕ ሩጽ ከመ ትፈትኖ በመልእክት ዘትጽሕፍ፤ በ Python ዘወፅአ፣ ሩጾ በጊዜሁ ወያወሥእ መልእክታተ እሙናተ።","tip":"በ Python ዘወፅአ፡ ግበር bot ምስለ @BotFather፣ ደይ token ውስተ second-thought.ini፣ ወእምዝ ሩጽ run-on-schedule። ያወሥእ ተናግሮተከ ባሕቲቶ (TELEGRAM_CHAT_ID)።"},
"a_discord":{"title":"bot ዘ Discord ዘያወሥእ ጥያቄያተ ኅብዘት","desc":"ሶበ ይሴአል መኑሂ ጥያቄ በፈለገ Discord ዘዚአከ፣ ላእክ ያወሥኦ፣ እንዘ ይገብር ሐሳበ በኈላቊ፣ ወያወሥእ በውእቱ ፈለግ። ጥቅዕ ሩጽ ከመ ትፈትኖ በጥያቄ ዘትጽሕፍ።","tip":"በ Python ዘወፅአ፡ ግበር bot ዘ Discord ምስለ intent ዘ Message Content፣ ደይ token ዘዚአሁ ወ id ዘፈለግከ ውስተ second-thought.ini፣ ወእምዝ ሩጽ run-on-schedule። ያነብብ አፍላገ ዘትዜኑ ባሕቲቶሙ። ወልጥ ግንፋላተ ዘኅብረ ጽጌረዳ በዘ Slack ከመ ትትበቋዕ በ Slack ህየንቴሁ።"},
"a_linkedin":{"title":"ላእክ፡ ርከብ ሰብአ በ LinkedIn","desc":"የኀሥሥ በገጻተ LinkedIn ገሃዳውያን ሰብአ ወማኅበራተ በነገር፣ ወይዜኑ መኑ እሙንቱ፣ ምንተ ይገብሩ ወበእንተ ምንት ይደሉ ትትራከቦሙ። ይረክብ ዘያርኢ LinkedIn ለኵሉ ባሕቲቱ፣ በኅሠሣ መርበብ።","tip":"ወልጥ ነገረ ወመካነ። Python ዘወፅአ የኀሥሥ በአማን፤ ዝንቱ ገጽ ያወሥእ እምአእምሮተ Claude።"},
"a_mqtt":{"title":"ላእክ፡ ሕትት መለክያነ (MQTT)","desc":"ያነብብ መለክያነ MQTT ዘዚአከ (Zigbee2MQTT ወካልኣን)፣ ያርኢ ኵሎ ዘኢልሙድ፣ ከመ ነጠብጣበ ማይ፣ battery ዘደክመ አው መሰኪ ዘተኀድገ ርኅወ፣ ወያቀርብ ያጥፍእ ነገራተ፣ እንዘ ይሴአለከ ቅድመ።","tip":"Python ዘወፅአ፡ አንብር MQTT_HOST። ወልጥ ነገራተ በፍጻሜ ኀበ ይሰብኩ ንዋያቲከ።"},
"y_goodnight":{"title":"ላእክ፡ ሌሊት ሠናይ ዘ Homey","desc":"ላእክ ይኔጽር በ Homey ዘዚአከ፡ ያጠፍእ ማኅቶታተ ዘተኀድጉ (እንዘ ይሴአለከ ቅድመ፣ ወየኀድግ ማኅቶተ መዓርግ)፣ ይሔትት ኆኃተ ወመዓጹተ ወይዜንዎሙ ባሕቲቱ፣ ወይነግረከ በእንተ batteries ዘደክሙ። በዝንቱ ገጽ ይትበቋዕ በቤተ አርአያ።","tip":"Python ዘወፅአ፡ አንብር HOMEY_URL ወ HOMEY_API_KEY። በል 'ኢትግበር' ለአሐዱ እምስእለታቲሁ ወየሐውር ዘእንበለ ውእቱ።"},
"y_washer":{"title":"Homey፡ ተፈጸመ ኅፅበት","desc":"የዐቅብ ኀይለ መኪና ኅፅበት በ Homey። ሶበ ይወርድ ታሕተ 5 W፣ Claude ይጽሕፍ ተዝካረ ኀጺረ ወይፌንዎ ለ Telegram። ጥቅዕ ሩጽ ከመ ትፈትኖ በኀይል ዘትጽሕፍ።","tip":"ወልጥ ስመ ንዋይ ኀበ መሰኪከ። Python ዘወፅአ ይሔትት በበ 10 ካልኢት እንዘ ይረውጽ በጊዜሁ።"},
"y_proofer":{"title":"Homey፡ ዕቀብ ሣፁነ ብሑእ በርትዕ","desc":"ያነብብ ሙቀተ ሣፁነ ብሑእ እም Homey ወ፣ እመ ፈድፋደ ምዉቅ፣ ያጠፍእ መሰኪ መምዉቁ ወይነግረከ በእንተ ምንት። እመ ፈድፋደ ቈሪር፣ ያበርሆ።","tip":"ወልጥ አስማተ ንዋያት ኀበ ዘዚአከ። ወስክ ግንፋለ 'ሶበ ይትዌለጥ ንዋየ ቤት ዘ Homey …' ከመ ትሩጾ ኵሎ ጊዜ ሶበ ይትዌለጥ ሙቀት።"},
"y_energy":{"title":"Homey፡ አይቴ የሐውር ኀይል?","desc":"ያነብብ ኵሎ ንዋየ ቤት ዘ Homey ዘይሜጥን ኀይለ ወያስተረጕም Claude፣ በቃል ግሁድ፣ ምንት ይትበቋዕ ፈድፋደ ወምንተ ታጥፍእ።","tip":"ሩጾ በምሴት፣ ሶበ ይደሉ ይኩን ዕጽወ መብዝኅተ ነገር።"},
"y_bakeday":{"title":"Homey፡ ወጥን ሥርዐተ ኅብዘት","desc":"ይኌልቍ ኅብስተ ዛቲ ሱባዔ በተወላጤ Homey፣ ይወጥን ውሒዘከ 'Baking mode'፣ ወይነግረከ ዘይገብር Homey ዘዚአከ። ውሒዛቲከ ይክሉ ይትበቋዑ በተወላጢ እምዝ።","tip":"ግበር ውሒዘ ዘስሙ 'Baking mode' በ Homey፣ ወተወላጤ ኍልቍ ዘስሙ 'Loaves this week'።"},
"h_gifts":{"title":"ሐሳባተ አምኃ በውስተ መስፈርት","desc":"ያመክር ስድስተ አምኃተ ዘተሠርዑ በሤጥ፣ የኀድገከ ትኅረይ አሐደ፣ ወእምዝ ይጽሕፍ መልእክተ ጦማረ አምኃ ሎቱ።","tip":"ሀብ መስፈርተ ወኅዳጠ እምዘያፈቅሩ።"},
