"ha_fridge":{"title":"ዕቅበተ መዝገበ ቍር ወመዝገበ በረድ","desc":"በበ 30 ደቃይቅ፣ ይጌሥጸከ እመ ዐርገ መዝገበ ቍር ላዕለ 5°C አው መዝገበ በረድ ላዕለ -15°C። ይትበቋዕ በቤተ አርአያ በገጽ፣ ወበ Home Assistant ዘዚአከ እሙን በ Python ዘወፅአ።","tip":"ወልጥ ሙቀተ በገበታ ከመ ትፈትን ተግሣጸ።"},
"ha_starter":{"title":"ተዝካረ ምግበ ብሑእ","desc":"በ 08:00፣ ያነብብ ሙቀተ ቤተ መብስል ወያመክር ማእዜ ትሴስዮ ለብሑእ ዮም፣ ወበአይ መጠን። ይትበቋዕ በቤተ አርአያ በገጽ፣ ወበ Home Assistant ዘዚአከ እሙን በ Python ዘወፅአ።","tip":"በል መጠነከ ልሙደ በጥያቄ።"},
"ha_oven":{"title":"እቶን ተኀድገ ርኅወ","desc":"ሶበ ይወፅእ ሰብእ ደኃሪ፣ ይሔትት እቶነ ወይፌኑ ተግሣጸ ፍጡነ እመ ዓዲ ይነድድ። ይትበቋዕ በቤተ አርአያ በገጽ፣ ወበ Home Assistant ዘዚአከ እሙን በ Python ዘወፅአ።","tip":"በገበታ፣ አንብር switch.oven ኀበ on፣ ወእምዝ person.alex ኀበ not_home።"},
"ha_dinner":{"title":"ምንት ለድራር?","desc":"ያመክር ሠለስተ ድራራተ እምዘሀሎ በዝርዝረ ምሥያጥከ ወበቤተ መብስል፣ ምስለ ዘዓዲ ትፈቅድ። ይትበቋዕ በቤተ አርአያ በገጽ፣ ወበ Home Assistant ዘዚአከ እሙን በ Python ዘወፅአ።","tip":"ይትበቋዕ በዝርዝረ ምሥያጥ ዘ Home Assistant።"},
"ha_chores":{"title":"ተራ ግብረ ቤት ርቱዕ","desc":"ኵሎ ሱባዔ፣ ጸሐፍ መኑ ገብረ ምንተ፤ ይዜከር፣ ወእምዝ ይጽሕፍ ተራ ርቱዐ ለሱባዔ ዘይመጽእ። ይትበቋዕ በቤተ አርአያ በገጽ፣ ወበ Home Assistant ዘዚአከ እሙን በ Python ዘወፅአ።","tip":"ሩጾ በምሴተ እሑድ ምስለ ቤተ ሰብእ።"},
"ha_laundry":{"title":"ተፈጸመ ኅፅበት","desc":"ሶበ ይወርድ ኀይለ መኪና ኅፅበት፣ ይነግረከ ከመ ተፈጸመ ኅፅበት። ይትበቋዕ በቤተ አርአያ በገጽ፣ ወበ Home Assistant ዘዚአከ እሙን በ Python ዘወፅአ።","tip":"በገበታ፣ ወልጥ ኀይለ መኪና ኅፅበት ኀበ 400 ወእምዝ 2።"},
"ha_dishwasher":{"title":"ንጹሕኑ መኪና ኅፅበተ ንዋይ?","desc":"ያወሥእ ጥያቄ ዘለዓለም እምህላዌ መኪና ኅፅበተ ንዋይ፣ በአሐዱ ነገር ፍቁር። ይትበቋዕ በቤተ አርአያ በገጽ፣ ወበ Home Assistant ዘዚአከ እሙን በ Python ዘወፅአ።","tip":"ወስኮ ለመጥቅዐ ሰሌዳ ርእይ አው ስአሎ በቃል።"},
"ha_bedtime":{"title":"ነገረ ንዋም በመጫወቲ","desc":"በ 19:30፣ ያደክም ማኅቶተ ቤተ ንዋም ወያነብብ ነገረ ንዋም ሐዲሰ ኀጺረ በመጫወቲ ዘቤተ ደቂቅ። ይትበቋዕ በቤተ አርአያ በገጽ፣ ወበ Home Assistant ዘዚአከ እሙን በ Python ዘወፅአ።","tip":"ወልጥ ስመ ሕፃን ወዘያፈቅር በስእለተ ነገር።"},
"ha_checkin":{"title":"ሐተታ የዋህ ለዘመድ","desc":"በ 10:00፣ እመ አልቦ ሑሰት በቤተ ገቦ ኵሎ ጽባሐ፣ ይፌኑ ጥያቄ የዋሀ 'ኵሉኑ ዳኅን?' ለቤተ ሰብእ። ይትበቋዕ በቤተ አርአያ በገጽ፣ ወበ Home Assistant ዘዚአከ እሙን በ Python ዘወፅአ።","tip":"ተሰነአው በዝንቱ ምስለ ውእቱ ሰብእ ቅድመ፤ ኅብአተ ነገሩ ውእቱ ካዕበ።"},
"ha_petcam":{"title":"ምንተ ይገብር ከልብ?","desc":"ይነሥእ ሥዕለ እም camera ዘእንስሳ ቤት ወይነግረከ፣ በአሐዱ ነገር፣ ምንተ ይገብር እንስሳከ። ይትበቋዕ በቤተ አርአያ በገጽ፣ ወበ Home Assistant ዘዚአከ እሙን በ Python ዘወፅአ።","tip":"ወስክ 'ወይሔይክኑ ዘኢይደሉ?'"},
"ha_feeder":{"title":"ገብረኑ መሴስይ?","desc":"በ 09:00፣ ይሔትት ከመ ወሀበ መሴስይ በዛቲ ጽባሕ ወእመ ይውሕድ ሲሳይ። ይትበቋዕ በቤተ አርአያ በገጽ፣ ወበ Home Assistant ዘዚአከ እሙን በ Python ዘወፅአ።","tip":"አስተሳንእ ጊዜ ኀበ ድኅረ ጊዜ መሴስይ።"},
"ha_petheat":{"title":"ቤተ እንስሳ ፈድፋደ ምዉቅ","desc":"በበ 15 ደቃይቅ፣ ይጌሥጸከ እመ ኀለፈ ቤት ዘሀሎ እንስሳከ 26°C። ይትበቋዕ በቤተ አርአያ በገጽ፣ ወበ Home Assistant ዘዚአከ እሙን በ Python ዘወፅአ።","tip":"አትሕቶ ለእለ ነዊኅ ጸጕሮሙ።"},
"ha_batteries":{"title":"batteries ዘይትዌለጡ","desc":"ይረክብ ኵሎ battery ዘታሕተ 20% ወይዌልጦሙ ኀበ ዝርዝረ ምሥያጥ ዘተሠርዐ በበ ቤት፣ ምስለ ዘመደ battery ዘይመስል። ይትበቋዕ በቤተ አርአያ በገጽ፣ ወበ Home Assistant ዘዚአከ እሙን በ Python ዘወፅአ።","tip":"ሩጾ አሐተ ጊዜ በወርኅ ወኢትደነግፅ በመለኪያ ዘሞተ ግሙራ።"},
"ha_offline":{"title":"ምንት ወፅአ እመርበብ?","desc":"ይዜኑ ኵሎ entity ዘኢይትረከብ ወያመክር ምክንያተ ወተራትዖ ዘይመስል ለለ አሐዱ። ይትበቋዕ በቤተ አርአያ በገጽ፣ ወበ Home Assistant ዘዚአከ እሙን በ Python ዘወፅአ።","tip":"ንዋያተ ቤተ ንዋይ ወቤተ ሰረገላ ይወድቁ ብዙኀ ጊዜ ሶበ ይቈርር።"},
"ha_maintenance":{"title":"ዕቅበት ዘበጽሐ ጊዜሁ","desc":"ያነብብ ዕለታተ ዕቅበትከ (መምዉቀ ማይ፣ ተግሣጸ ጢስ፣ መጽረይያን) ወይዜኑ ዘኀለፈ ጊዜሁ አው ዘቅሩብ። ይትበቋዕ በቤተ አርአያ በገጽ፣ ወበ Home Assistant ዘዚአከ እሙን በ Python ዘወፅአ።","tip":"ግበር helper ዘ input_datetime ለለ ግብር በ Home Assistant።"},
"ha_leak":{"title":"ነጠብጣበ ማይ!","desc":"ሶበ ይረጥብ መለኪያ ነጠብጣብ፣ ይፌኑ ተግሣጸ ፍጡነ ወይሰብክ ነገራተ ቀደምተ ዘይትገበሩ። ይትበቋዕ በቤተ አርአያ በገጽ፣ ወበ Home Assistant ዘዚአከ እሙን በ Python ዘወፅአ።","tip":"በገበታ፣ አንብር binary_sensor.leak_kitchen ኀበ on።"},
"ha_waterflow":{"title":"ነቅዐ ማይ ዘያንጠበጥብ አው ነጠብጣብ ኅቡእ","desc":"በ 04:00፣ ሶበ አልቦ ዘይደሉ ይሩጽ፣ ይሔትት መለኪያ ማይ ወይጌሥጸከ በእንተ ውሒዝ ንኡስ ዘኢየኀልቅ። ይትበቋዕ በቤተ አርአያ በገጽ፣ ወበ Home Assistant ዘዚአከ እሙን በ Python ዘወፅአ።","tip":"ይገብር ምስለ ዘኮነ መለኪያ ማይ አው መለኪያ ውሒዝ።"},
"ha_servers":{"title":"ጥዒና አገልጋይ በአሐዱ መስመር","desc":"ያነብብ መለክያነ Proxmox፣ disk ወዕቅበት ዘዚአከ ወይሁብ አሐደ መስመረ በቃል ግሁድ እፎ ሀሎ homelab። ይትበቋዕ በቤተ አርአያ በገጽ፣ ወበ Home Assistant ዘዚአከ እሙን በ Python ዘወፅአ።","tip":"ይትበቋዕ በመለክያነ Proxmox integration፤ አስተሳንኦ ምስለ ዘዚአከ።"},
"ha_pihole":{"title":"ጥቅላለ Pi-hole","desc":"ጥቅላል ኀጺር ወቀሊል ለአንብቦ ዘከልአ Pi-hole ዮም ወእመ ቦ ዘይመስል ዘኢልሙድ። ይትበቋዕ በቤተ አርአያ በገጽ፣ ወበ Home Assistant ዘዚአከ እሙን በ Python ዘወፅአ።","tip":"ይትበቋዕ በመለክያነ Pi-hole integration።"},
