"{what} was refused, so nothing happened.":"{what} ተከልአ፣ በእንተዝ አልቦ ዘኮነ።",
"{who} returned nothing for this step. Simplify it and try again.":"{who} አልቦ ዘአግብአ ለዝንቱ መዓርግ። አቅልሎ ወፈትን ዳግመ።",
"{who}: {tokens_in} tokens in, {tokens_out} out":"{who}፡ {tokens_in} token ቦኡ፣ {tokens_out} ወፅኡ",
"{x}  ·  MCP {version}":"{x}  ·  MCP {version}",
"{x} failed: {x2}\nTrying {x3} instead.":"{x} ወድቀ፡ {x2}\nይፈትን {x3} ህየንቴሁ።",
"{x} is empty. Put the command that starts the server there.":"{x} ዕራቅ ውእቱ። ደይ ህየ ትእዛዘ ዘይወጥን አገልጋየ።",
"{x} is set (Perplexity has no free way to try it, so it isn't checked further)":"{x} ተነብረ (Perplexity አልቦቱ ፍኖት ዘበከንቱ ለፈተና፣ በእንተዝ ኢይትሐተት ፈድፋደ)",
"“{entity}” isn't an entity id. Use something like light.kitchen.":"“{entity}” ኢኮነ id ዘ entity። ተበቋዕ በዘከመ light.kitchen።",
"“{hhmm}” isn't a time like 09:00.":"“{hhmm}” ኢኮነ ጊዜ ከመ 09:00።",
"“{kind}” isn't a type the agent knows. Use text, number, yes/no, list or any (for “{name}”).":"“{kind}” ኢኮነ ዘመደ ዘየአምር ላእክ። ተበቋዕ በ text, number, yes/no, list አው any (ለ“{name}”)።",
"“{name}” can't run while other scripts are running at the same time. Run it from a script that runs on its own (not alongside a broadcast).":"“{name}” ኢይክል ይሩጽ እንዘ ይረውጹ ፍኖታት ካልኣን በአሐዱ ጊዜ። ሩጾ እምፍኖት ዘይረውጽ ባሕቲቱ (አኮ ምስለ ስብከት)።",
"“{repo}” isn't a GitHub project. Use owner/name, like octocat/hello-world.":"“{repo}” ኢኮነ ግብረ GitHub። ተበቋዕ በ owner/name፣ ከመ octocat/hello-world።",
"“{service}” isn't a service name. Use domain.service, for example light.turn_off.":"“{service}” ኢኮነ ስመ አገልግሎት። ተበቋዕ በ domain.service፣ በአርአያ light.turn_off።",
"“{text}” isn't a day. Use today, tomorrow, a weekday or YYYY-MM-DD.":"“{text}” ኢኮነ ዕለተ። ተበቋዕ በ today, tomorrow፣ ዕለተ ሱባዔ አው YYYY-MM-DD።",
"“{to}” isn't an email address.":"“{to}” ኢኮነ መካነ email።",
"“{value}” isn't a number.":"“{value}” ኢኮነ ኍልቈ።",
"“{value}” isn't on or off.":"“{value}” ኢኮነ on አው off።",
"“{x}” isn't a real date.":"“{x}” ኢኮነ ዕለተ እሙነ።",
"“{x}” isn't a time.":"“{x}” ኢኮነ ጊዜ።",
"any smart home action (Home Assistant, Homey or MQTT)":"ኵሉ ግብረ ቤት ጠቢብ (Home Assistant, Homey አው MQTT)",
"sending messages and announcements":"ፈንዎተ መልእክታት ወዜናት",
"saving files":"ዐቂበ መጻሕፍት",
"all of these":"ኵሎሙ እሉ",
