"It may have been retired. To use another without changing the program, put a model it does list in second-thought.ini, such as {settings}.":"ዮጊ ተስዕረ። ከመ ትትበቋዕ በካልእ ዘእንበለ ትወልጥ ሥርዐተ፣ ደይ አምሳለ ዘይዜኑ ውስተ second-thought.ini፣ ከመ {settings}።",
"There's no scheduled script {n}: this program has {count}.":"አልቦ ፍኖት ዘበጊዜ {n}፡ ዝንቱ ሥርዐት ቦቱ {count}።",
"Not time for scheduled script {n} ({time}, {days}), so nothing was run.":"ኢኮነ ጊዜሁ ለፍኖት ዘበጊዜ {n} ({time}, {days})፣ በእንተዝ አልቦ ዘሮጸ።",
"weekdays":"መዋዕለ ግብር",
"weekends":"ሰንበታት",
