"the keychain":"መዝገበ መራኁት",
"Keys":"መራኁት",
"Keychain":"መዝገበ መራኁት",
"keyring is installed but the keychain couldn't be read ({problem}), so keys only come from the environment and second-thought.ini":"keyring ተተክለ ወባሕቱ መዝገበ መራኁት ኢተነበ ({problem})፣ በእንተዝ መራኁት ይመጽኡ እም environment ወ second-thought.ini ባሕቲቶሙ",
"MCP tool":"ንዋየ MCP",
"with --mcp, it serves one tool, “{name}”, to Claude and other agents":"ምስለ --mcp፣ ያቀርብ አሐደ ንዋየ፣ “{name}”፣ ለ Claude ወለካልኣን ላእካን",
"This program can act on the world and hasn't been allowed to without asking. Run it once in a terminal and answer y, or put approve = no in second-thought.ini.":"ዝንቱ ሥርዐት ይክል ይግበር በዓለም ወኢተበውሐ ዘእንበለ ተስእሎ። ሩጾ አሐተ ጊዜ በ terminal ወአውሥእ y፣ አው ደይ approve = no ውስተ second-thought.ini።",
"MCP call":"ጽዋዔ MCP",
"Test answer":"ተሰጥዎተ ፈተና",
"Test cases don't keep pictures, so a test can't choose one. Test this part by running the program.":"ፈተናት ኢየዐቅቡ ሥዕላተ፣ በእንተዝ ፈተና ኢትክል ትኅረይ አሐደ። ፈትን ዘንተ ክፍለ በሩጸተ ሥርዐት።",
"Test {n}":"ፈተና {n}",
"Test: {name}":"ፈተና፡ {name}",
"The run stopped.":"ቆመት ሩጸት።",
"The test case has no answer for this step ({what}). Save it again from a run that gets this far.":"ፈተና አልባቲ ተሰጥዎ ለዝንቱ መዓርግ ({what})። ዕቀባ ዳግመ እምሩጸት እንተ ትበጽሕ እስከ ዝየ።",
"replayed":"ተደግመ",
"{passed} of {n} passed.":"{passed} እም {n} ኀለፉ።",
"No tests: {path} isn't there. Make them on the page: after a good run, press Save as test case, then export again.":"አልቦ ፈተናት፡ {path} ኢሀሎ። ግበሮሙ በገጽ፡ ድኅረ ሩጸት ሠናይት፣ ጥቅዕ ዕቀብ ከመ ፈተና፣ ወእምዝ አውፅእ ዳግመ።",
"Not done, because this is a test: {what}":"ኢተገብረ፣ እስመ ዝንቱ ፈተና፡ {what}",
