"Test run":"ሩጸተ ፈተና",
"{path} isn't valid JSON ({problem}).":"{path} ኢኮነ JSON ርቱዐ ({problem})።",
"Choose a file":"ኅረይ መጽሐፈ",
"Choose one":"ኅረይ አሐደ",
"\nThis program has changed since you allowed it on {when}.":"\nዝንቱ ሥርዐት ተወለጠ እምዘ አባሕኮ አመ {when}።",
"\nThis program has changed since you allowed it.":"\nዝንቱ ሥርዐት ተወለጠ እምዘ አባሕኮ።",
"New since then: {what}":"ሐዲስ እምአሜሃ፡ {what}",
"No longer: {what}":"ኢኮነ እንከ፡ {what}",
"What it can do is the same as before.":"ዘይክል ይግበር ከመ ዘቀደመ ውእቱ።",
"{changes} Run it once yourself and answer y (a scheduled run won't start until then).":"{changes} ሩጾ አሐተ ጊዜ ለሊከ ወአውሥእ y (ሩጸት ዘበጊዜ ኢትወጥን እስከ ውእቱ)።",
"about {cost}":"ከመ {cost}",
"under {cost}":"ዘይንእስ እም {cost}",
"{cost} at list prices":"{cost} በሤጠ ዝርዝር",
"Claude refused the key. Check ANTHROPIC_API_KEY {where_keys}.":"Claude ከልአ መርኆ። ሕትት ANTHROPIC_API_KEY {where_keys}።",
"Fix the problem above, then start it again with Run workflow on the Actions tab.":"አስተራትዕ ጌጋየ ዘበላዕሉ፣ ወእምዝ ወጥኖ ዳግመ በ Run workflow በክፍለ Actions።",
"Run stopped: {msg}":"ቆመት ሩጸት፡ {msg}",
"Your Claude account is out of credit. Add some at https://console.anthropic.com, then run it again.":"መዝገበ Claude ዘዚአከ ኀልቀ credit። ወስክ በ https://console.anthropic.com፣ ወእምዝ ሩጾ ዳግመ።",
"Your Claude key belongs to a whole Console organisation, not one workspace. Make a key inside a workspace (the Console's Workspaces page), or set ANTHROPIC_WORKSPACE_ID {where_keys}.":"መርኆ Claude ዘዚአከ ዘማኅበረ Console ኵለንታሁ ውእቱ፣ አኮ ዘአሐዱ workspace። ግበር መርኆ ውስተ workspace (ገጸ Workspaces ዘ Console)፣ አው አንብር ANTHROPIC_WORKSPACE_ID {where_keys}።",
"as a repository secret (Settings → Secrets and variables → Actions)":"ከመ ምሥጢረ repository (Settings → Secrets and variables → Actions)",
"Claude declined to answer this step. Look at what it was given (the step's prompt, in the log or the saved log), and word it another way or leave out what it was reading.":"Claude አበየ ያውሥእ ዘንተ መዓርገ። ነጽር ዘተውህበ ሎቱ (ትእዛዘ መዓርግ፣ በመዝገብ አው በመዝገብ ዘተዐቅበ)፣ ወበሎ በካልእ ቃል አው ኅድግ ዘያነብብ።",
"Claude returned nothing for this step (it stopped with “{stop}”). Simplify it and try again.":"Claude አልቦ ዘአግብአ ለዝንቱ መዓርግ (ቆመ በ“{stop}”)። አቅልሎ ወፈትን ዳግመ።",
"Stopped · 1 model call":"ቆመ · 1 ጽዋዔ አምሳል",
"Stopped · {n} model calls":"ቆመ · {n} ጽዋዔያተ አምሳል",
"Runtime":"ሥርዐተ ሩጸት (runtime)",
"{version} is the latest":"{version} ውእቱ ዘሐዲስ",
"couldn't check for a newer one ({err})":"ኢተክህለ ሐቲተ ዘይሔድስ ({err})",
"{latest} is out, with a security fix (this program has {version}). {how}":"{latest} ወፅአ፣ ምስለ ተራትዖ ዕቅበት (ዝንቱ ሥርዐት ቦቱ {version})። {how}",
"{latest} is out (this program has {version}). {how}":"{latest} ወፅአ (ዝንቱ ሥርዐት ቦቱ {version})። {how}",
"Run it with --update-runtime to get it.":"ሩጾ ምስለ --update-runtime ከመ ትርከቦ።",
"Import this file on the Second Thought page and export it again to get it.":"አብእ ዘንተ መጽሐፈ በገጸ Second Thought ወአውፅኦ ዳግመ ከመ ትርከቦ።",
"Import this file on the Second Thought page and export it again.":"አብእ ዘንተ መጽሐፈ በገጸ Second Thought ወአውፅኦ ዳግመ።",
"This file doesn't mark where its runtime starts and ends, so it can't be updated in place.":"ዝንቱ መጽሐፍ ኢያመለክት ኀበ ይወጥን ወየኀልቅ runtime ዘዚአሁ፣ በእንተዝ ኢይትሐደስ በመካኑ።",
"Couldn't check for a newer runtime ({err}).":"ኢተክህለ ሐቲተ runtime ዘይሔድስ ({err})።",
"Runtime {latest} is a new major version, which may change what this program does, so it isn't applied here.":"Runtime {latest} ሕትመት ዐቢይ ሐዲስ ውእቱ፣ ዘዮጊ ይዌልጥ ዘይገብር ዝንቱ ሥርዐት፣ በእንተዝ ኢይትገበር በዝየ።",
"Runtime {version} is the latest, so there's nothing to update.":"Runtime {version} ውእቱ ዘሐዲስ፣ በእንተዝ አልቦ ዘይትሐደስ።",
"Release {latest} has no runtime to download.":"release {latest} አልቦቱ runtime ለአውርዶ።",
"The downloaded runtime doesn't match its SHA-256, so it wasn't used. Nothing was changed.":"runtime ዘወረደ ኢይሰነአው ምስለ SHA-256 ዘዚአሁ፣ በእንተዝ ኢተበቍዑ ቦቱ። አልቦ ዘተወለጠ።",
"The downloaded runtime isn't a {latest} runtime, so it wasn't used. Nothing was changed.":"runtime ዘወረደ ኢኮነ runtime {latest}፣ በእንተዝ ኢተበቍዑ ቦቱ። አልቦ ዘተወለጠ።",
"Couldn't write {path} ({err}). Nothing was changed.":"ኢተክህለ ጽሒፈ {path} ({err})። አልቦ ዘተወለጠ።",
"Updated the runtime from {version} to {latest}. The old file is saved as {backup}.":"ተሐደሰ runtime እም {version} ኀበ {latest}። መጽሐፍ ብሉይ ተዐቅበ ከመ {backup}።",
"What changed: {url}":"ዘተወለጠ፡ {url}",
"The file changed, so it asks to be allowed again before its next run.":"መጽሐፍ ተወለጠ፣ በእንተዝ ይስእል ይትበዋሕ ዳግመ ቅድመ ሩጸቱ እንተ ትመጽእ።",
"No money budget for this run.":"አልቦ መስፈርተ ወርቅ ለዛቲ ሩጸት።",
"Stopped: a model this run has already used has no known price, so it can't be held to its budget of {x}. Use models with a price, or a budget in tokens.":"ቆመት፡ አምሳል ዘተበቍዐት ቦቱ ዛቲ ሩጸት ቅድመ አልቦቱ ሤጥ ዘይትዐወቅ፣ በእንተዝ ኢትትዐቀብ በመስፈርታ {x}። ተበቋዕ በአምሳላት ዘቦሙ ሤጥ፣ አው በመስፈርት ዘ token።",
"Stopped: this run has spent {x} at list prices, which reaches its budget of {x2}. Raise the amount in the 'limit this run' block (or budget_dollars in second-thought.ini).":"ቆመት፡ ዛቲ ሩጸት አውፅአት {x} በሤጠ ዝርዝር፣ ዘይበጽሕ መስፈርታ {x2}። አልዕል መጠነ በግንፋለ 'ወስን ዛተ ሩጸተ' (አው budget_dollars ውስተ second-thought.ini)።",
"Stopped: {model} has no known price, so this run can't be held to its budget of {x}. Use a model with a price, or a budget in tokens.":"ቆመት፡ {model} አልቦቱ ሤጥ ዘይትዐወቅ፣ በእንተዝ ዛቲ ሩጸት ኢትትዐቀብ በመስፈርታ {x}። ተበቋዕ በአምሳል ዘቦቱ ሤጥ፣ አው በመስፈርት ዘ token።",
"This run stops before a model call once it has spent {x} at list prices (spent so far: {x2}).":"ዛቲ ሩጸት ትቀውም ቅድመ ጽዋዔ አምሳል ሶበ አውፅአት {x} በሤጠ ዝርዝር (ዘወፅአ እስከ ይእዜ፡ {x2})።",
"Currency":"ወርቅ",
"Today's rate couldn't be fetched ({err}), so it uses the last one it has.":"ሚዛነ ዮም ኢተረክበ ({err})፣ በእንተዝ ይትበቋዕ በደኃሪ ዘቦቱ።",
"at the ECB rate of {date}":"በሚዛነ ECB ዘ {date}",
"at the rate set {where_keys}":"በሚዛን ዘተነብረ {where_keys}",
"currency must be usd, gbp, eur, jpy or cny, not “{raw}”. Fix it {where_keys}.":"currency ይኩን usd, gbp, eur, jpy አው cny፣ አኮ “{raw}”። አስተራትዖ {where_keys}።",
